package ejerciciosElementosDePrograma;

public class Ejercicio1_5 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
/* 5. Programa que calcula el área de una circunferencia de radio 5,2 centímetros (π r2 )
 * Formula para el area de una circunferencia area = pi * r²
 */
	double radio = 5.2;
	double pi = 3.14;
	double area = (radio * radio) * pi;
	System.out.println("Area de la circunferencia: "+area+"m²");
	}

}
